const clamp=x=>Math.max(0,Math.min(1,x));const smooth=x=>{x=clamp(x);return x*x*x*(x*(x*6-15)+10)};
// Integral of quintic smoothstep: continuous positive-speed ramp, no lookup steps.
const integralSmooth=t=>t**6-3*t**5+2.5*t**4;
export function revealTime(u,input={}){const f={...eyeJourneyDefaults,...input};u=clamp(u);if(!f.historyRevealSlowEnabled)return u;const a=Math.max(0,Math.min(.85,f.historyRevealSlowStart)),b=Math.max(a+.06,Math.min(.94,f.historyRevealSlowEnd)),entry=Math.min(b,a+.08),slow=Math.max(.08,Math.min(1,f.historyRevealSlowSpeed)),fast=Math.max(1,Math.min(5,f.historyRevealFastSpeed));function integrate(t){if(t<=a)return t;let sum=a;const v=Math.min(t,entry)-a,q=v/(entry-a);sum+=v+(slow-1)*(entry-a)*integralSmooth(q);if(t<=entry)return sum;sum+=slow*(Math.min(t,b)-entry);if(t<=b)return sum;const w=t-b,r=w/(1-b);return sum+slow*w+(fast-slow)*(1-b)*integralSmooth(r);}return integrate(u)/integrate(1);}
export function revealSettings(input={}){const f={...eyeJourneyDefaults,...input},finish=Math.max(.25,Math.min(1,f.historyRevealFinish)),start=Math.max(0,Math.min(finish-.015,f.historyRevealStart));return {...f,historyRevealStart:start,historyRevealFinish:finish};}
export function projectDepthRect(rect,camera,depth=1){const [x,y,w,h]=rect,z=Math.pow(Math.max(1,camera.zoom),depth);return [480+(x-480)*z-(camera.x-480)*z*depth,270+(y-270)*z-(camera.y-270)*z*depth,w*z,h*z];}
export function eyeJourneyState(age,input={}){const f=revealSettings(input),raw=clamp(age/3.267),p=revealTime(raw/f.historyRevealFinish,f),depth=Math.max(.2,f.historyEyeFrontDepth),aspect=f.historyRevealShape==='circle'?1:Math.max(.5,Math.min(1.3,f.historyIrisAspect)),baseRadius=Math.max(1,f.historyIrisRadius),endZoom=Math.max(2,f.historyIrisEndZoom,1.12*Math.hypot(480/aspect,270)/baseRadius),zoom=Math.exp(Math.log(endZoom)/depth*p**4),pan=smooth(p/.8),eyeX=f.historyEyeX??586,eyeY=f.historyEyeY??312,camera={zoom,x:480+(eyeX-480)*pan/depth,y:270+(eyeY-270)*pan/depth},z=Math.pow(zoom,depth),cx=480+(eyeX-480)*z-(camera.x-480)*z*depth,cy=270+(eyeY-270)*z-(camera.y-270)*z*depth,radius=baseRadius*z,endRadius=baseRadius*endZoom,reframe=smooth((radius-90)/Math.max(1,1.12*Math.hypot(480/aspect,270)-90)),onset=revealTime(f.historyRevealStart/f.historyRevealFinish,f),reveal=smooth((p-onset)/Math.max(.0001,1-onset));return {progress:p,raw,camera,cx,cy,radius,reframe,reveal,blur:f.historyIrisBlur*smooth((p-.7)/.2)*(1-reframe),reflection:f.historyIrisReflection+(1-f.historyIrisReflection)*reframe};}

let exterior,destination,iris;
function canvas(){return Object.assign(document.createElement('canvas'),{width:960,height:540});}
export function paintEyeJourney(c,age,input,paintExterior,paintDestination){const f=revealSettings(input),s=eyeJourneyState(age,f);exterior||=canvas();destination||=canvas();iris||=canvas();const b=exterior.getContext('2d'),d=destination.getContext('2d'),m=iris.getContext('2d');b.clearRect(0,0,960,540);b.imageSmoothingEnabled=true;b.imageSmoothingQuality='high';const shift=paintExterior(b,{warCameraZoom:s.camera.zoom,warCameraX:s.camera.x,warCameraY:s.camera.y,warFrontDepth:f.historyEyeFrontDepth,warRearDepth:f.historyEyeRearDepth,warLandDepth:f.historyEyeLandDepth,warSkyDepth:f.historyEyeSkyDepth,revealClock:3.267*s.progress});if(Number.isFinite(shift?.focusShiftX)){s.cx+=shift.focusShiftX;s.cy+=shift.focusShiftY;if(Math.abs(shift.focusShiftX)+Math.abs(shift.focusShiftY)>.001){const aspect=f.historyRevealShape==='circle'?1:Math.max(.5,Math.min(1.3,f.historyIrisAspect)),cover=1.12*Math.max(...[0,960].flatMap(x=>[0,540].map(y=>Math.hypot((x-s.cx)/aspect,y-s.cy))));s.radius+=Math.max(0,cover-s.radius)*smooth((s.progress-.88)/.12);}}c.save();c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';c.filter=`blur(${s.blur}px)`;c.drawImage(exterior,0,0);c.restore();if(s.reveal<=0)return s;
 d.clearRect(0,0,960,540);paintDestination(d);m.clearRect(0,0,960,540);const aspect=f.historyRevealShape==='circle'?1:Math.max(.5,Math.min(1.3,f.historyIrisAspect)),rx=s.radius*aspect,ry=s.radius,q=s.reframe,x=(s.cx-rx)*(1-q),y=(s.cy-ry)*(1-q),w=2*rx*(1-q)+960*q,h=2*ry*(1-q)+540*q,k=Math.max(w/960,h/540)*(1+(Math.max(1,f.historyRevealContentScale)-1)*(1-q)),iw=960*k,ih=540*k,focusX=f.historyRevealContentX*(1-q)+.5*q,focusY=f.historyRevealContentY*(1-q)+.5*q;
 // Cover-fit the destination; retain its aspect rather than squeezing it into an oval.
 m.save();m.imageSmoothingEnabled=true;m.imageSmoothingQuality='high';m.globalAlpha=s.reveal*s.reflection;m.drawImage(destination,x+w/2-focusX*iw,y+h/2-focusY*ih,iw,ih);m.globalAlpha=1;m.globalCompositeOperation='destination-in';m.translate(s.cx,s.cy);m.scale(aspect,1);if(f.historyRevealShape==='rectangle'){const g=m.createLinearGradient(-s.radius,0,s.radius,0);for(const [at,color]of [[0,'#fff0'],[.07,'#fff'],[.93,'#fff'],[1,'#fff0']])g.addColorStop(at,color);m.fillStyle=g;m.fillRect(-s.radius,-s.radius,s.radius*2,s.radius*2);const v=m.createLinearGradient(0,-s.radius,0,s.radius);for(const [at,color]of [[0,'#fff0'],[.07,'#fff'],[.93,'#fff'],[1,'#fff0']])v.addColorStop(at,color);m.fillStyle=v;m.fillRect(-s.radius,-s.radius,s.radius*2,s.radius*2);}else{const mask=m.createRadialGradient(0,0,0,0,0,Math.max(1,s.radius));mask.addColorStop(0,'#fff');mask.addColorStop(.93,'#fff');mask.addColorStop(1,'#fff0');m.fillStyle=mask;m.fillRect(-s.radius,-s.radius,s.radius*2,s.radius*2);}m.restore();c.drawImage(iris,0,0);
 // Original eye remains underneath. A small light catch survives until the room takes over.
 if(q<1){c.save();c.globalAlpha=.075*s.reveal*(1-q);c.fillStyle='#fff';c.beginPath();c.ellipse(s.cx-rx*.22,s.cy-ry*.27,Math.max(.4,rx*.06),Math.max(.4,ry*.04),0,0,7);c.fill();c.restore();}return s;
}
// Standalone adapter: usable outside the template without knowing its shot names.
export function focusRevealState(elapsed,{duration=3.267,...settings}={}){return eyeJourneyState(3.267*elapsed/Math.max(.1,duration),settings);}
export function paintFocusReveal(c,elapsed,{duration=3.267,...settings}={},paintSource,paintDestination){return paintEyeJourney(c,3.267*elapsed/Math.max(.1,duration),settings,paintSource,paintDestination);}
